def gen(rng):
    def fmt(p, d):
        return str(len(p)) + '\n' + ' '.join(map(str, p)) + '\n' + ' '.join(map(str, d))
    tests = [fmt([5], [100]), fmt([1, 1, 1, 1], [3, 3, 3, 3]), fmt([10, 20, 30], [1, 5, 2]),
             fmt([10**9, 10**9], [1, 10**5]), fmt([1, 1000], [10, 1])]
    for n in (2, 3, 4, 5, 6, 7):
        for _ in range(3):
            tests.append(fmt([rng.randint(1, 30) for _ in range(n)], [rng.randint(1, 10) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(100000)], [rng.randint(1, 10**5) for _ in range(100000)]))
    tests.append(fmt([10**9] * 100000, [10**5] * 100000))
    tests.append(fmt([1] * 100000, [rng.randint(1, 10**5) for _ in range(100000)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(99999)], list(range(1, 100000))))
    return tests

